// @generated by:gauntlet run:godseye-local-hermes-tools
import { createHash, randomBytes, randomUUID } from "node:crypto";
import { InfrastructureEngine } from "@godseye/core";
import { schema } from "@godseye/store";
import { eq } from "drizzle-orm";
import { expect, it } from "vitest";
import { createHermesProvider } from "../apps/control-api/src/hermes-provider.js";
import { createHermesToolExecutor } from "../apps/control-api/src/hermes-tool-executor.js";
import { agentsFixture } from "./helpers/agents-fixture.js";
import { nativeBootDiagnostic, nativeModelFixture } from "./helpers/agents-native-fixture.js";
import { toolsPolicy, toolsSelection } from "./helpers/agents-tools-fixture.js";

const native = process.env.GODSEYE_TEST_HERMES_TOOLS_NATIVE === "1";

it.skipIf(!native).each(["success", "call-limit", "cost-limit"] as const)(
  "T-AC-763 T-AC-769 T-AC-770 actual pinned Hermes/Foundation/isolated tools enforce %s",
  async (scenario) => {
    const fixture = await agentsFixture();
    const content = "A harmless result created by the isolated typed tool.";
    const model = await nativeModelFixture({
      toolsScript: [
        { name: "godseye_workspace_write", arguments: { path: "artifacts/report.txt", content } },
        { name: "godseye_workspace_read", arguments: { path: "artifacts/report.txt" } },
        ...(scenario === "call-limit"
          ? [
              { name: "godseye_workspace_read", arguments: { path: "scratch/input.txt" } },
              { name: "godseye_workspace_read", arguments: { path: "artifacts/report.txt" } },
            ]
          : []),
      ],
    });
    const provider = createHermesProvider({
      fixtureBaseUrl: model.baseUrl,
      bindings: [
        {
          projectId: fixture.project.id,
          environmentId: fixture.development.id,
          role: "operations",
          apiKey: randomBytes(24).toString("hex"),
        },
      ],
    });
    const executor = createHermesToolExecutor();
    const engine = new InfrastructureEngine(fixture.store, {
      ...fixture.configuration,
      now: () => new Date(),
      agents: { provider, toolExecutor: executor, pollMs: 100 },
    });
    const actor = () => ({ ...fixture.freshOwner(), authenticatedAt: new Date().toISOString() });
    let taskId: string | undefined;
    try {
      const policy = toolsPolicy({ timeoutSeconds: 30 });
      const profile = await engine.agents.createProfile(
        actor(),
        {
          ...fixture.profileInput,
          toolPolicy: policy,
          limits: {
            ...fixture.profileInput.limits,
            timeoutSeconds: 300,
            maxRequests: scenario === "call-limit" ? 4 : 3,
            maxTurns: scenario === "call-limit" ? 4 : 3,
            maxCostMicros:
              scenario === "cost-limit" ? 3000 : scenario === "call-limit" ? 30000 : 10000,
          },
        },
        randomUUID(),
      );
      const conversation = await engine.agents.chatCreate(
        actor(),
        {
          profileId: profile.id,
          expectedRevision: profile.revision,
          title: "Actual isolated tool qualification",
        },
        randomUUID(),
      );
      const launched = await engine.agents.chatSend(
        actor(),
        conversation.conversation.id,
        {
          expectedRevision: conversation.conversation.revision,
          input: "Write the harmless copied artifact, read it, and finish.",
          toolGrant: {
            ...toolsSelection(policy),
            maxModelRequests: scenario === "call-limit" ? 4 : 3,
          },
        },
        randomUUID(),
      );
      taskId = launched.turns[0]?.task.id;
      if (!taskId) throw new Error("Actual tool qualification has no admitted task");

      expect(await engine.foundation.tick("native-hermes-tools-qualified-worker")).toBe(true);

      const detail = await engine.agents.detail(actor(), taskId);
      const tools = await engine.agents.toolsDetail(actor(), taskId);
      const stats = (await model.stats()) as {
        requests: {
          tools: boolean;
          offeredTools: string[];
          toolResponses: { callId: string; sha256: string }[];
        }[];
      };
      console.info(
        JSON.stringify({
          kind: "actual-hermes-tools-foundation-chain",
          taskId,
          taskState: detail.task.state,
          reason: detail.task.reason,
          modelRequests: stats.requests.length,
          toolCalls: tools.calls.length,
          toolStates: tools.calls.map((call) => call.state),
          allocationState: tools.state,
          physicallyStopped: tools.stopped,
        }),
      );
      const usage = (await nativeBootDiagnostic(taskId, "usage")) as {
        requests: number;
        reservedCostMicros: number;
      };
      expect(usage.requests).toBe(stats.requests.length);
      expect(usage.reservedCostMicros).toBeGreaterThan(0);
      expect(usage.reservedCostMicros).toBeLessThanOrEqual(profile.limits.maxCostMicros);
      expect(tools).toMatchObject({ state: "stopped", stopped: true });
      if (scenario !== "success") {
        expect(detail.task.state).not.toBe("succeeded");
        expect(detail.task.output).toBeNull();
        expect(
          (await engine.agents.chatDetail(actor(), conversation.conversation.id)).artifacts,
        ).toEqual([]);
        if (scenario === "call-limit") {
          expect(stats.requests).toHaveLength(4);
          expect(tools.calls).toHaveLength(3);
          expect(tools.calls.every((call) => call.state === "succeeded")).toBe(true);
        } else {
          expect(stats.requests.length).toBeGreaterThan(0);
          expect(stats.requests.length).toBeLessThan(3);
        }
        return;
      }
      expect(detail.task).toMatchObject({
        state: "succeeded",
        output: "Hermes native fixture finished safely.",
      });
      expect(tools).toMatchObject({ state: "stopped", stopped: true });
      expect(tools.calls.map((call) => ({ name: call.name, state: call.state }))).toEqual([
        { name: "godseye_workspace_write", state: "succeeded" },
        { name: "godseye_workspace_read", state: "succeeded" },
      ]);
      expect(stats.requests).toHaveLength(3);
      expect(stats.requests.every((request) => request.tools)).toBe(true);
      expect(stats.requests[0]?.offeredTools.slice().sort()).toEqual(policy.tools.slice().sort());
      expect(stats.requests[1]?.toolResponses).toHaveLength(1);
      expect(stats.requests[2]?.toolResponses).toHaveLength(2);
      const [allocation] = await fixture.store.db
        .select()
        .from(schema.agentToolAllocations)
        .where(eq(schema.agentToolAllocations.taskId, taskId));
      expect(allocation?.request).toMatchObject({
        taskId,
        projectId: fixture.project.id,
        environmentId: fixture.development.id,
        correlationId: taskId,
      });
      expect(allocation?.receipt?.profileHash).toBe(profile.hash);
      const final = await engine.agents.chatDetail(actor(), conversation.conversation.id);
      const artifact = final.artifacts.find((entry) => entry.content === content);
      expect(artifact).toMatchObject({
        content,
        bytes: Buffer.byteLength(content),
        sha256: createHash("sha256").update(content).digest("hex"),
      });
      expect((await engine.foundation.getBudget(actor(), fixture.project.id)).reservedMicros).toBe(
        0,
      );
    } finally {
      if (taskId) await engine.agents.cancel(actor(), taskId, randomUUID()).catch(() => undefined);
      await provider.close();
      await executor.close();
      await model.close();
      await fixture.store.close();
    }
  },
  360000,
);
